/* ─── STORAGE ────────────────────────────────────────────────── */
const sGet  = async (key)      => { try { const r = await window.storage.get(key, true);  return r?.value || null; } catch { return null; } };
const sSet  = async (key, val) => { try { await window.storage.set(key, val, true); return true; } catch { return false; } };
const sList = async (prefix)   => { try { const r = await window.storage.list(prefix, true); return r?.keys || []; } catch { return []; } };

/* ─── IMAGE COMPRESSION ─────────────────────────────────────── */
const compressImg = (file, maxDim = 900, quality = 0.78) =>
  new Promise((resolve, reject) => {
    if (file.size > 6 * 1024 * 1024) { reject(new Error("File too large. Max 6MB.")); return; }
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const ratio = Math.min(1, maxDim / Math.max(img.width, img.height));
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(img.width * ratio);
        canvas.height = Math.round(img.height * ratio);
        canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  });

