                <button onClick={() => setStep(1)} style={{ background: "#f5f4f0", border: `1px solid ${BORDER}`, borderRadius: 3, padding: "6px 14px", fontSize: 10, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase", cursor: "pointer", color: "#555", flexShrink: 0 }}>Edit</button>
